<template>
  <teleport to="body"><div class="fixed inset-0 z-[70] bg-black/45 p-4 flex items-center justify-center" @click.self="requestClose"><section class="w-full max-w-5xl max-h-[92vh] overflow-hidden bg-surface-elevated border border-border rounded-panel shadow-overlay flex flex-col" role="dialog" aria-modal="true" aria-labelledby="document-composer-title" data-testid="client-document-composer">
    <header class="p-6 border-b border-border-muted flex items-start justify-between gap-4"><div><p class="type-overline text-ink-muted">Client document</p><h2 id="document-composer-title" class="text-h2 font-semibold text-ink mt-1">{{ document ? 'Edit Document' : 'Create Document' }}</h2><p class="text-body-sm text-ink-secondary mt-1">Drafts are saved to Helio. Only completed clinical session notes can be selected as source material.</p></div><button type="button" aria-label="Close document composer" class="text-ink-muted hover:text-ink" @click="requestClose">✕</button></header>
    <div class="flex-1 overflow-auto p-6"><div v-if="loading" class="py-16 text-center text-ink-muted">Loading document workspace…</div><div v-else class="grid grid-cols-1 lg:grid-cols-[minmax(0,1fr)_300px] gap-6"><div class="space-y-5">
      <label class="block"><span class="text-caption font-semibold text-ink">Title</span><input v-model="form.title" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="e.g. Clinical summary – August 2026" /></label>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4"><label class="block"><span class="text-caption font-semibold text-ink">Document type</span><select v-model="form.documentType" class="mt-1 w-full p-3 border border-border rounded-control bg-surface"><option value="clinical_summary">Clinical summary</option><option value="progress_report">Progress report</option><option value="care_letter">Care letter</option><option value="other">Other</option></select></label><label class="block"><span class="text-caption font-semibold text-ink">Recipient</span><input v-model="form.recipient" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="Optional" /></label></div>
      <label class="block"><span class="text-caption font-semibold text-ink">Purpose</span><input v-model="form.purpose" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" placeholder="Why this document is being prepared" /></label>
      <div class="grid grid-cols-1 md:grid-cols-2 gap-4"><label class="block"><span class="text-caption font-semibold text-ink">Period start</span><input v-model="form.periodStart" type="date" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label><label class="block"><span class="text-caption font-semibold text-ink">Period end</span><input v-model="form.periodEnd" type="date" class="mt-1 w-full p-3 border border-border rounded-control bg-surface" /></label></div>
      <label class="block"><span class="flex items-center justify-between gap-3"><span class="text-caption font-semibold text-ink">Document body</span><span v-if="selectedSourceIds.length" class="text-caption text-ink-muted">Sources: {{ selectedSourceIds.length }} session{{ selectedSourceIds.length === 1 ? '' : 's' }}</span></span><textarea v-model="form.body" rows="16" class="mt-1 w-full p-4 border border-border rounded-control bg-surface resize-y" placeholder="Write the document here. You can add selected session notes from the source panel." /></label>
    </div><aside class="lg:max-h-[60vh] flex flex-col min-h-0 border border-border rounded-panel bg-surface-subtle overflow-hidden" data-testid="clinical-source-panel"><div class="p-4 border-b border-border-muted"><div class="flex items-center justify-between gap-2"><h3 class="text-body-sm font-semibold text-ink">Clinical sources</h3><span class="text-caption text-ink-muted">{{ selectedSourceIds.length }} selected</span></div><p class="text-caption text-ink-muted mt-1">Private reflections and supervision material are not available here.</p><input v-model="sourceQuery" type="search" class="mt-3 w-full p-2.5 border border-border rounded-control bg-surface text-body-sm" placeholder="Search session notes…" aria-label="Search clinical sources" /><label v-if="filteredSources.length" class="mt-3 flex items-center gap-2 text-caption text-ink-secondary"><input type="checkbox" :checked="allFilteredSelected" @change="toggleAllFiltered" /> Select all shown</label></div><div class="flex-1 min-h-0 overflow-y-auto p-2 space-y-1" data-testid="clinical-source-list"><div v-if="sources.length === 0" class="p-3 text-body-sm text-ink-muted">No completed session notes are available for this client.</div><div v-else-if="filteredSources.length === 0" class="p-3 text-body-sm text-ink-muted">No session notes match your search.</div><div v-for="source in filteredSources" :key="source.id" class="border border-border rounded-control bg-surface"><div class="flex items-center gap-2 p-2.5"><input v-model="selectedSourceIds" type="checkbox" :value="source.id" :aria-label="`Select session ${formatDate(source.occurredAt)}`" /><button type="button" class="min-w-0 flex-1 text-left" @click="togglePreview(source.id)"><strong class="block text-body-sm text-ink">{{ formatDate(source.occurredAt) }}</strong><span class="block text-caption text-ink-muted">Clinical session note · v{{ source.version }}</span></button><span v-if="addedSourceIds.includes(source.id)" class="text-caption text-state-success font-semibold">Added</span><button type="button" class="text-caption text-ink-muted hover:text-ink px-1" :aria-expanded="expandedSourceId === source.id" :aria-label="`${expandedSourceId === source.id ? 'Hide' : 'Preview'} session note ${formatDate(source.occurredAt)}`" @click="togglePreview(source.id)">{{ expandedSourceId === source.id ? 'Hide' : 'Preview' }}</button></div><div v-if="expandedSourceId === source.id" class="px-3 pb-3 text-body-sm text-ink-secondary whitespace-pre-wrap border-t border-border-muted pt-3">{{ source.notes || 'No note text' }}</div></div></div><div class="p-3 border-t border-border-muted bg-surface-elevated"><button type="button" class="button-secondary w-full" :disabled="addableSelectedSources.length === 0" @click="appendSources">{{ addableSelectedSources.length ? `Add ${addableSelectedSources.length} selected note${addableSelectedSources.length === 1 ? '' : 's'} to draft` : (selectedSources.length ? 'Selected notes already added' : 'Add selected notes to draft') }}</button></div></aside></div><div v-if="error" class="mt-5 p-4 rounded-control bg-state-danger/10 text-state-danger" role="alert">{{ error }}</div></div>
    <footer class="p-6 border-t border-border-muted flex flex-wrap items-center justify-between gap-4"><p class="text-caption text-ink-muted">{{ saveMessage }}</p><div class="flex flex-wrap gap-2"><button type="button" class="button-secondary" :disabled="saving" @click="requestClose">Close</button><button type="button" class="button-secondary" :disabled="saving || !form.title.trim()" @click="previewDocument">Preview / Print</button><button type="button" class="button-secondary" :disabled="saving || !form.title.trim()" @click="saveDraft">{{ saving ? 'Saving…' : 'Save Draft' }}</button><button type="button" class="button-primary" :disabled="saving || !form.title.trim() || !form.body.trim()" @click="finaliseDocument">{{ saving ? 'Working…' : 'Finalise PDF' }}</button></div></footer>
  </section></div></teleport>
</template>
<script setup>
import { computed,onMounted,reactive,ref } from 'vue';
import { createClientDocumentDraft,finaliseClientDocument,listDocumentSourceSessions,openDocumentPrintView,saveClientDocumentDraft } from '../../lib/clientDocuments.js';
const props=defineProps({client:{type:Object,required:true},document:{type:Object,default:null}});const emit=defineEmits(['close','saved']);
const loading=ref(true),saving=ref(false),error=ref(''),saveMessage=ref('Unsaved changes'),sources=ref([]),selectedSourceIds=ref([]),addedSourceIds=ref([]),expandedSourceId=ref(null),sourceQuery=ref(''),currentDocument=ref(props.document);
const form=reactive({title:props.document?.title||'',documentType:props.document?.documentType||'clinical_summary',recipient:props.document?.recipient||'',purpose:props.document?.purpose||'',periodStart:props.document?.periodStart||'',periodEnd:props.document?.periodEnd||'',body:props.document?.content?.body||''});
const selectedSources=computed(()=>sources.value.filter(source=>selectedSourceIds.value.includes(source.id)));
const addableSelectedSources=computed(()=>selectedSources.value.filter(source=>!addedSourceIds.value.includes(source.id)));
const filteredSources=computed(()=>{const query=sourceQuery.value.trim().toLowerCase();if(!query)return sources.value;return sources.value.filter(source=>`${formatDate(source.occurredAt)} ${source.notes||''}`.toLowerCase().includes(query));});
const allFilteredSelected=computed(()=>filteredSources.value.length>0&&filteredSources.value.every(source=>selectedSourceIds.value.includes(source.id)));
onMounted(async()=>{try{sources.value=await listDocumentSourceSessions(props.client.id);const ids=new Set((props.document?.sourceManifest||[]).filter(item=>item.kind==='session').map(item=>item.id));selectedSourceIds.value=sources.value.filter(source=>ids.has(source.id)).map(source=>source.id);addedSourceIds.value=[...selectedSourceIds.value];}catch(e){console.error('Failed to load document sources:',e);error.value='Could not load completed session notes.';}finally{loading.value=false;}});
function sourceManifest(){return selectedSources.value.map(source=>({kind:'session',id:source.id,version:source.version,occurredAt:source.occurredAt}));}
function changes(){return{title:form.title,documentType:form.documentType,recipient:form.recipient,purpose:form.purpose,periodStart:form.periodStart||null,periodEnd:form.periodEnd||null,content:{body:form.body},sourceManifest:sourceManifest()};}
function appendSources(){const pending=addableSelectedSources.value;if(!pending.length)return;const text=pending.map(source=>`Session ${formatDate(source.occurredAt)}\n${source.notes||''}`.trim()).join('\n\n');if(text)form.body=[form.body.trim(),text].filter(Boolean).join('\n\n');addedSourceIds.value=[...new Set([...addedSourceIds.value,...pending.map(source=>source.id)])];saveMessage.value=`Added ${pending.length} session note${pending.length===1?'':'s'} to draft · unsaved`;}
function togglePreview(id){expandedSourceId.value=expandedSourceId.value===id?null:id;}
function toggleAllFiltered(event){const ids=filteredSources.value.map(source=>source.id);if(event.target.checked)selectedSourceIds.value=[...new Set([...selectedSourceIds.value,...ids])];else selectedSourceIds.value=selectedSourceIds.value.filter(id=>!ids.includes(id));}
async function persistDraft(){currentDocument.value=currentDocument.value?await saveClientDocumentDraft(currentDocument.value,changes()):await createClientDocumentDraft({client:props.client,...changes()});saveMessage.value=`Saved ${new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})}`;emit('saved',currentDocument.value);return currentDocument.value;}
async function saveDraft(){if(saving.value||!form.title.trim())return;saving.value=true;error.value='';try{await persistDraft();}catch(e){console.error('Failed to save document draft:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:'Could not save this document draft.';}finally{saving.value=false;}}
async function previewDocument(){if(saving.value)return;saving.value=true;error.value='';try{const draft=await persistDraft();openDocumentPrintView(draft,props.client);}catch(e){console.error('Failed to preview document:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:(e.message||'Could not preview this document.');}finally{saving.value=false;}}
async function finaliseDocument(){if(saving.value||!form.body.trim())return;if(!window.confirm('Finalise this document? The saved PDF will become read-only.'))return;saving.value=true;error.value='';try{const draft=await persistDraft();currentDocument.value=await finaliseClientDocument(draft);saveMessage.value='Finalised as PDF';emit('saved',currentDocument.value);emit('close');}catch(e){console.error('Failed to finalise document:',e);error.value=e.code==='DOCUMENT_CONFLICT'?e.message:(e.message||'Could not finalise this document.');}finally{saving.value=false;}}
function requestClose(){if(!saving.value)emit('close');}
function formatDate(value){return value?new Date(value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}):'Date unavailable';}
</script>
